public class OpportunityPipelineHandler {

    public static void handleAfterInsert(List<Opportunity> newOpps) {
        recalculateAccounts(newOpps, null);
    }

    public static void handleAfterUpdate(Map<Id, Opportunity> newMap, Map<Id, Opportunity> oldMap) {
        List<Opportunity> affectedOpps = new List<Opportunity>();

        // Only process opportunities where relevant fields actually changed
        for (Opportunity newOpp : newMap.values()) {
            Opportunity oldOpp = oldMap.get(newOpp.Id);
            if (oldOpp != null && 
                (newOpp.Amount != oldOpp.Amount || 
                 newOpp.IsClosed != oldOpp.IsClosed || 
                 newOpp.AccountId != oldOpp.AccountId)) {
                affectedOpps.add(newOpp);
            }
        }

        if (!affectedOpps.isEmpty()) {
            recalculateAccounts(affectedOpps, oldMap);
        }
    }

    public static void handleAfterDelete(Map<Id, Opportunity> oldMap) {
        recalculateAccounts(oldMap.values(), null);
    }

    public static void handleAfterUndelete(List<Opportunity> newOpps) {
        recalculateAccounts(newOpps, null);
    }

    private static void recalculateAccounts(List<Opportunity> affectedOpps, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();

        // Collect account IDs from current opportunities
        for (Opportunity opp : affectedOpps) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }

        // For updates, also collect old account IDs if they differ (opportunity moved)
        if (oldMap != null) {
            for (Opportunity opp : affectedOpps) {
                Opportunity oldOpp = oldMap.get(opp.Id);
                if (oldOpp != null && oldOpp.AccountId != null && oldOpp.AccountId != opp.AccountId) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Query all open opportunities for affected accounts
        List<Opportunity> openOpps = [
            SELECT Id, AccountId, Amount 
            FROM Opportunity 
            WHERE AccountId IN :accountIds AND IsClosed = false
        ];

        // Initialize rollup values for all affected accounts
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();

        for (Id accId : accountIds) {
            pipelineByAccount.put(accId, 0);
            countByAccount.put(accId, 0);
        }

        // Sum up the open opportunities
        for (Opportunity opp : openOpps) {
            Decimal amount = opp.Amount != null ? opp.Amount : 0;
            pipelineByAccount.put(
                opp.AccountId, 
                pipelineByAccount.get(opp.AccountId) + amount
            );
            countByAccount.put(
                opp.AccountId, 
                countByAccount.get(opp.AccountId) + 1
            );
        }

        // Build account updates
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accId,
                FB_Open_Pipeline__c = pipelineByAccount.get(accId),
                FB_Open_Opportunities__c = countByAccount.get(accId)
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
