public class LogPurgeJob implements Schedulable {

    // No-argument constructor
    public LogPurgeJob() {
    }

    // Execute method from Schedulable interface
    public void execute(SchedulableContext context) {
        purgeOldLogs();
    }

    // Main purge logic
    private static void purgeOldLogs() {
        // Calculate dates
        Date thirtyDaysAgo = Date.today().addDays(-30);
        Date oneHundredEightyDaysAgo = Date.today().addDays(-180);

        // Convert to DateTime for CreatedDate comparison
        DateTime thirtyDaysAgoDateTime = DateTime.newInstanceGmt(thirtyDaysAgo, Time.newInstance(0, 0, 0, 0));
        DateTime oneHundredEightyDaysAgoDateTime = DateTime.newInstanceGmt(oneHundredEightyDaysAgo, Time.newInstance(0, 0, 0, 0));

        // Query records to delete
        // Delete non-ERROR logs older than 30 days
        // Delete ERROR logs older than 180 days
        List<FB_Integration_Log__c> recordsToDelete = [
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (CreatedDate < :thirtyDaysAgoDateTime AND (Level__c != 'ERROR' OR Level__c = NULL))
            OR (CreatedDate < :oneHundredEightyDaysAgoDateTime AND Level__c = 'ERROR')
        ];

        if (!recordsToDelete.isEmpty()) {
            delete recordsToDelete;
        }
    }

    // Schedule the job to run nightly at 02:00
    public static Id scheduleNightly() {
        // Cron expression for 02:00 every day
        // Format: Seconds Minutes Hours Day_of_month Month Day_of_week
        String cronExpression = '0 0 2 * * ?';

        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
