        }

        // Calculate current year date range
        Integer currentYear = System.today().year();
        Date yearStart = Date.newInstance(currentYear, 1, 1);
        Date yearEnd = Date.newInstance(currentYear, 12, 31);

        // Aggregate query to sum won opportunity amounts by account
        List<AggregateResult> aggregateResults = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsWon = true
            AND CloseDate >= :yearStart
            AND CloseDate <= :yearEnd
            GROUP BY AccountId
        ];

        // Update result map with aggregated values
        for (AggregateResult ar : aggregateResults) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');
            result.put(accountId, totalAmount != null ? totalAmount : 0);
        }

        return result;
    }
}
