        if (String.isBlank(reason)) {
            throw new EscalationException('Escalation reason cannot be blank');
        }

        // Do nothing if caseIds is null or empty
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Load cases using the selector
        ICasesSelector selector = CasesSelector.newInstance();
        List<Case> cases = selector.selectById(caseIds);

        // Get unit of work for batch operations
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Boolean hasChanges = false;

        // Process each case
        for (Case c : cases) {
            // Skip closed cases and already escalated cases
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            // Update case for escalation
            c.IsEscalated = true;
            c.Priority = 'High';
            uow.registerDirty(c);

            // Create escalation task
            Task escalationTask = new Task();
            escalationTask.Subject = 'Escalated: ' + reason;
            escalationTask.WhatId = c.Id;
            escalationTask.OwnerId = c.OwnerId;
            escalationTask.ActivityDate = System.today().addDays(1);
            escalationTask.Priority = 'High';
            uow.registerNew(escalationTask);

            hasChanges = true;
        }

        // Commit changes only if there are cases to escalate
        if (hasChanges) {
            uow.commitWork();
        }
    }
}
