public class RenewalReminderService {
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Query opportunities with required fields
        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        Integer successCount = 0;

        for (Opportunity opp : opportunities) {
            try {
                Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
                email.setTargetObjectId(opp.OwnerId);
                email.setSaveAsActivity(false);
                email.setSubject('Renewal due: ' + opp.Name);

                String body = 'Your opportunity is due for renewal.\n\n';
                body += 'Close Date: ' + (opp.CloseDate != null ? opp.CloseDate.format() : 'Not specified');
                email.setPlainTextBody(body);

                Messaging.SendEmailResult[] results = Messaging.sendEmail(
                    new List<Messaging.SingleEmailMessage>{ email }
                );

                if (results[0].isSuccess()) {
                    successCount++;
                } else {
                    System.debug(LoggingLevel.WARN, 'Email failed for opportunity ' + opp.Id + ': ' + results[0].getErrors());
                }
            } catch (Exception e) {
                System.debug(LoggingLevel.ERROR, 'Exception sending renewal reminder for opportunity ' + opp.Id + ': ' + e.getMessage());
            }
        }

        return successCount;
    }
}
