public class AccountCountrySync {
    /**
     * Syncs account billing country changes to related contacts' mailing country.
     * When an account's BillingCountry changes, updates contacts whose MailingCountry
     * is blank or matches the old BillingCountry to the new value.
     * 
     * Bulk-safe: Single query loads all related contacts into a map, no queries in loops.
     */
    public static void handleAccountUpdate(Map<Id, Account> newAccountMap, Map<Id, Account> oldAccountMap) {
        // Load all related contacts in a single query
        Map<Id, List<Contact>> contactsByAccountId = new Map<Id, List<Contact>>();

        for (Contact contact : [
            SELECT Id, AccountId, MailingCountry 
            FROM Contact 
            WHERE AccountId IN :newAccountMap.keySet()
        ]) {
            if (!contactsByAccountId.containsKey(contact.AccountId)) {
                contactsByAccountId.put(contact.AccountId, new List<Contact>());
            }
            contactsByAccountId.get(contact.AccountId).add(contact);
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // Process each account that had an update
        for (Id accountId : newAccountMap.keySet()) {
            Account newAccount = newAccountMap.get(accountId);
            Account oldAccount = oldAccountMap.get(accountId);

            // Only process if BillingCountry actually changed
            if (newAccount.BillingCountry != oldAccount.BillingCountry) {
                String newBillingCountry = newAccount.BillingCountry;
                String oldBillingCountry = oldAccount.BillingCountry;

                // Get contacts for this account (already loaded in map)
                List<Contact> accountContacts = contactsByAccountId.get(accountId);
                if (accountContacts != null) {
                    for (Contact contact : accountContacts) {
                        // Update if MailingCountry is blank or matches the old BillingCountry
                        if (String.isBlank(contact.MailingCountry) || contact.MailingCountry == oldBillingCountry) {
                            contact.MailingCountry = newBillingCountry;
                            contactsToUpdate.add(contact);
                        }
                    }
                }
            }
        }

        // Bulk update all contacts at once
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
