import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    @api contacts;

    get hasContacts() {
        return this.contacts && Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        // Create a copy to avoid mutating the parent's array
        return [...this.contacts].sort((a, b) => {
            return a.Name.localeCompare(b.Name);
        });
    }

    get contactCount() {
        if (!this.contacts || !Array.isArray(this.contacts)) {
            return 0;
        }
        return this.contacts.length;
    }

    get countText() {
        const count = this.contactCount;
        if (count === 1) {
            return '1 contact';
        }
        return `${count} contacts`;
    }
}
