import { LightningElement, wire } from 'lwc';
import { MessageContext, subscribe, unsubscribe, publish, APPLICATION_SCOPE } from 'lightning/messageService';
import Account_Selected from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
  messageContext;
  selectedAccountId = null;
  subscription = null;
  isConnected = false;

  @wire(MessageContext)
  wiredMessageContext(value) {
    this.messageContext = value;
    if (this.isConnected) {
      this.subscribeToChannel();
    }
  }

  connectedCallback() {
    this.isConnected = true;
    this.subscribeToChannel();
  }

  disconnectedCallback() {
    this.isConnected = false;
    this.unsubscribeFromChannel();
  }

  subscribeToChannel() {
    if (this.isConnected && this.messageContext && !this.subscription) {
      this.subscription = subscribe(
        this.messageContext,
        Account_Selected,
        (message) => this.handleMessage(message),
        { scope: APPLICATION_SCOPE }
      );
    }
  }

  unsubscribeFromChannel() {
    if (this.subscription) {
      unsubscribe(this.subscription);
      this.subscription = null;
    }
  }

  handleMessage(message) {
    this.selectedAccountId = message.recordId || null;
  }

  handleClearClick() {
    const messagePayload = { recordId: null };
    publish(this.messageContext, Account_Selected, messagePayload);
  }

  get showForm() {
    return this.selectedAccountId !== null && this.selectedAccountId !== undefined;
  }
}
