import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
  waiting = 0;
  longestWaitMinutes = 0;
  error = null;
  isLoading = false;
  isConnected = false;
  pollInterval = null;
  visibilityListener = null;

  connectedCallback() {
    this.isConnected = true;
    // Load stats immediately
    this.loadStats();
    // Start polling every 60 seconds
    this.startPolling();
    // Listen for visibility changes
    this.visibilityListener = () => this.handleVisibilityChange();
    document.addEventListener('visibilitychange', this.visibilityListener);
  }

  disconnectedCallback() {
    this.isConnected = false;
    // Stop polling
    this.stopPolling();
    // Remove visibility listener
    if (this.visibilityListener) {
      document.removeEventListener('visibilitychange', this.visibilityListener);
      this.visibilityListener = null;
    }
  }

  loadStats() {
    // Skip if not connected, already loading, or document is hidden
    if (!this.isConnected || this.isLoading || document.visibilityState === 'hidden') {
      return;
    }

    this.isLoading = true;
    getQueueStats()
      .then((result) => {
        // Only update if still connected
        if (this.isConnected) {
          this.waiting = result.waiting;
          this.longestWaitMinutes = result.longestWaitMinutes;
          this.error = null;
        }
        this.isLoading = false;
      })
      .catch((error) => {
        // Only update if still connected
        if (this.isConnected) {
          this.error = error;
        }
        this.isLoading = false;
      });
  }

  startPolling() {
    this.pollInterval = setInterval(() => {
      this.loadStats();
    }, 60000); // 60 seconds
  }

  stopPolling() {
    if (this.pollInterval) {
      clearInterval(this.pollInterval);
      this.pollInterval = null;
    }
  }

  handleVisibilityChange() {
    if (document.visibilityState === 'visible') {
      // Page became visible, load immediately
      this.loadStats();
    }
  }
}
