     * - Marks any previous primary affiliation as Former, non-primary with end date of today
     * - Skips if the organization is already the primary affiliation
     * 
     * @param employerByContactId Map of Contact Id to Organization Account Id. Null or empty maps do nothing.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // SOQL 1: Get current primary affiliations for these contacts
        Map<Id, npe5__Affiliation__c> currentAffiliationByContactId = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
            AND npe5__Status__c = 'Current'
            AND npe5__Primary__c = true
        ]) {
            currentAffiliationByContactId.put(aff.npe5__Contact__c, aff);
        }

        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();

        // Process each contact
        for (Id contactId : contactIds) {
            Id newEmployerId = employerByContactId.get(contactId);
            npe5__Affiliation__c currentAff = currentAffiliationByContactId.get(contactId);

            // Skip if this organization is already the primary affiliation
            if (currentAff != null && currentAff.npe5__Organization__c == newEmployerId) {
                continue;
            }

            // Mark old affiliation as Former and non-primary with end date of today
            if (currentAff != null) {
                currentAff.npe5__Status__c = 'Former';
                currentAff.npe5__Primary__c = false;
                currentAff.npe5__EndDate__c = Date.today();
                affiliationsToUpdate.add(currentAff);
            }

            // Create new affiliation as Current and primary
            npe5__Affiliation__c newAff = new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = newEmployerId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = Date.today()
            );
            affiliationsToInsert.add(newAff);
        }

        // DML 1: Update old affiliations to Former/non-primary
        if (!affiliationsToUpdate.isEmpty()) {
            update affiliationsToUpdate;
        }

        // DML 2: Insert new affiliations as Current/primary
        // NPSP automation will update Contact.npsp__Primary_Affiliation__c
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }
}
