public class HouseholdService {
    public static Id createHousehold(List<Contact> members) {
        // Validate input
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Members list cannot be null or empty');
        }

        // Insert the first contact - NPSP will create a household for it
        Contact firstMember = members.get(0);
        insert firstMember;

        Id householdId = firstMember.AccountId;

        // If there are more members, insert them with the same household
        if (members.size() > 1) {
            List<Contact> remainingMembers = members.subList(1, members.size());
            for (Contact member : remainingMembers) {
                member.AccountId = householdId;
            }
            insert remainingMembers;
        }

        // Ensure the first contact is the primary contact
        Account household = new Account(Id = householdId);
        household.npe01__One2OneContact__c = firstMember.Id;
        update household;

        return householdId;
    }
}
