```apex
public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        // Check if user has read access to FB_Employee__c object
        SObjectType sObjectType = FB_Employee__c.SObjectType;
        DescribeSObjectResult describeResult = sObjectType.getDescribe();

        if (!describeResult.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Check field-level security for custom fields
        Map<String, SObjectField> fieldMap = describeResult.fields.getMap();
        Boolean canReadDepartment = isFieldAccessible(fieldMap, 'Department__c');
        Boolean canReadSalary = isFieldAccessible(fieldMap, 'Salary__c');
        Boolean canReadEmail = isFieldAccessible(fieldMap, 'Personal_Email__c');

        // Build dynamic SOQL query with only accessible fields
        String soqlQuery = 'SELECT Id, Name';
        if (canReadDepartment) {
            soqlQuery += ', Department__c';
        }
        if (canReadSalary) {
            soqlQuery += ', Salary__c';
        }
        if (canReadEmail) {
            soqlQuery += ', Personal_Email__c';
        }
        soqlQuery += ' FROM FB_Employee__c ORDER BY Name ASC';

        // Execute query (with sharing respects OWD and sharing rules)
        return Database.query(soqlQuery);
    }

    private static Boolean isFieldAccessible(Map<String, SObjectField> fieldMap, String fieldName) {
        SObjectField field = fieldMap.get(fieldName);
        if (field == null) {
            return false;
        }
        return field.getDescribe().isAccessible();
    }
}
