     * 
     * Efficiently handles bulk operations:
     * - Uses 1 SOQL query to fetch related Contacts
     * - Uses 2 DML statements (Account update, Contact update)
     * - Bypasses Account trigger actions to prevent expensive recalculation
     * - Allows Contact trigger actions to run normally
     * 
     * @param accountIds Set of Account IDs to reassign (up to 200)
     * @param newOwnerId ID of the new owner
     * @throws DmlException if any update fails (all-or-none semantics)
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Query for all Contacts related to the given Accounts
        List<Contact> contactsToUpdate = [SELECT Id FROM Contact WHERE AccountId IN :accountIds];

        // Build Account update list
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.add(new Account(Id = accId, OwnerId = newOwnerId));
        }

        // Bypass Account trigger actions
        TriggerBase.bypass('Account');

        try {
            // Update Accounts without trigger actions
            update accountsToUpdate;

            // Update Contacts with trigger actions running normally
            for (Contact c : contactsToUpdate) {
                c.OwnerId = newOwnerId;
            }
            update contactsToUpdate;
        } finally {
            // Always clear the bypass to restore normal Account automation
            // for any subsequent operations in the transaction
            TriggerBase.clearBypass('Account');
        }
    }
}
