File: force-app/main/default/classes/TA_Contact_InheritMailingAddress.cls
```apex
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        TA_Contact_Queries queries = TA_Contact_Queries.getInstance();

        for (SObject sObj : triggerNew) {
            Contact contact = (Contact) sObj;

            // Only process if contact has an account
            if (contact.AccountId == null) {
                continue;
            }

            // Only process if all four mailing fields are blank
            if (String.isEmpty(contact.MailingStreet) && 
                String.isEmpty(contact.MailingCity) && 
                String.isEmpty(contact.MailingPostalCode) && 
                String.isEmpty(contact.MailingCountry)) {

                Account account = queries.accountsById.get(contact.AccountId);
                if (account != null) {
                    contact.MailingStreet = account.BillingStreet;
                    contact.MailingCity = account.BillingCity;
                    contact.MailingPostalCode = account.BillingPostalCode;
                    contact.MailingCountry = account.BillingCountry;
                }
            }
        }
    }
}
